  function renderQRWFieldEditor(){return `<section class="panel qrw-field-editor" data-qrw-panel="3 4"><div class="section-head"><div><h3>Steps 3–4 · Desired JSON fields and value mapping</h3><p>Field names are operator-defined. Every value must have observed evidence, an approved deterministic derivation, or an explicit default.</p></div><div class="actions"><button type="button" class="secondary" data-action="qrw-suggest-fields">Suggest from raw log</button><button type="button" class="secondary" data-action="qrw-add-field">Add field</button><button type="button" class="secondary" data-action="qrw-test-fields">Test all fields</button><button type="button" class="secondary" data-action="qrw-save-draft">Save mapping draft</button></div></div><div class="table-wrap"><table class="qrw-field-table"><thead><tr><th>#</th><th>Name / label</th><th>Type / policy</th><th>Extraction</th><th>Transform / validation</th><th>Preview / evidence</th><th>Actions</th></tr></thead><tbody id="qrw-field-rows">${renderQRWFieldRows()||'<tr><td colspan="7"><div class="empty-state">Inspect a retained record, then request evidence-based suggestions or add a field manually.</div></td></tr>'}</tbody></table></div><div id="qrw-field-status" role="status" class="callout">No mapping has been validated. Unresolved fields are never fabricated.</div><div class="wizard-navigation"><button type="button" class="secondary qrw-back-button" data-action="qrw-navigate" data-step="2">2 · Back to evidence</button><button type="button" class="primary qrw-next-button" data-action="qrw-navigate" data-step="5">5 · Generate parser candidate</button></div></section>`;}

