    const linkedAsset=linkedCandidate&&(state.assuranceSyncAssets||[]).find(asset=>asset.asset_id===linkedCandidate.id),originClient=linkedAsset?.clients?.find(client=>client.node_id===originNode);
    const originAcknowledged=!!originClient&&!originClient.drifted&&!!originClient.applied_hash&&originClient.applied_hash===originClient.desired_hash;
